<script setup>
import {ref,onMounted} from 'vue';import {api,jsonBody} from '../api';import {auth,hasPermission} from '../auth';import {showConfirm} from '../uiDialogs';
const panel=ref(null),expected=ref([]),owners=ref([]),teachers=ref([]),error=ref(''),busy=ref(false),preview=ref(null);
const from=ref(''),to=ref(''),studentIds=ref(''),offboard=ref(false),reason=ref('');
const lesson=ref({campId:'',classId:'',lessonId:'',lessonName:'',plannedAt:''}),editing=ref(null);
async function load(){try{if(hasPermission('rankings.completeness.read')){panel.value=await api('/rankings/admin/completeness');expected.value=await api('/rankings/admin/expected-lessons');}if(auth.user?.admin){const d=await api('/rankings/admin/transfers');owners.value=d.ownerships;teachers.value=d.teachers;}}catch(e){error.value=e.message;}}
async function perform(work){if(busy.value)return;busy.value=true;error.value='';try{await work();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function transferPreview(){await perform(async()=>{preview.value=await api('/rankings/admin/transfers/preview',{method:'POST',body:jsonBody({from:from.value,to:to.value,studentIds:studentIds.value.split(/[，,\s]+/).filter(Boolean),offboard:offboard.value,reason:reason.value})});});}
async function confirmTransfer(){if(!await showConfirm('确认交接？剩余积分随学生转入新老师，旧会话失效；原订单仍由原老师处理。'))return;await perform(async()=>{await api(`/rankings/admin/transfers/${preview.value.previewId}/confirm`,{method:'POST'});preview.value=null;await load();});}
async function saveLesson(){await perform(async()=>{await api('/rankings/admin/expected-lessons'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:jsonBody({...lesson.value,plannedAt:new Date(lesson.value.plannedAt).toISOString()})});editing.value=null;lesson.value={campId:'',classId:'',lessonId:'',lessonName:'',plannedAt:''};await load();});}
function editLesson(e){editing.value=e.id;lesson.value={campId:e.camp_id,classId:e.class_id,lessonId:e.lesson_id,lessonName:e.lesson_name,plannedAt:new Date(new Date(e.planned_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)};}
async function removeLesson(e){if(await showConfirm('删除此预期课节？不会删除已导入的课程成绩。'))await perform(async()=>{await api('/rankings/admin/expected-lessons/'+e.id,{method:'DELETE'});await load();});}
async function resolve(o){if(!to.value||!reason.value.trim()){error.value='请先选择接收老师并填写核实依据';return;}if(await showConfirm('确认当前有效老师？历史余额不会自动合并。'))await perform(async()=>{await api('/rankings/admin/transfers/conflicts/'+encodeURIComponent(o.student_id),{method:'POST',body:jsonBody({owner:to.value,reason:reason.value})});await load();});}
onMounted(load);
</script>
<template><section class="continuity"><p v-if="error" class="notice notice-error" role="alert">{{error}}</p><section v-if="panel"><h2>数据完整性</h2><p>缺少课程记录仅表示待核实，不表示学员未完成课程；预期课节由老师维护。</p><div class="stats"><span>待开通 / 停用 {{panel.pendingAccounts.length}}</span><span>缺手机号 {{panel.missingPhones.length}}</span><span>异常批次 {{panel.importErrors.length}}</span><span>缺课节记录 {{panel.missingLessons.length}}</span><span>缺实际日期 {{panel.missingDates.length}}</span></div><details><summary>待开通名单</summary><p v-for="s in panel.pendingAccounts" :key="s.student_id">{{s.student_name}} · {{s.student_id}}</p></details><details><summary>导入异常</summary><p v-for="b in panel.importErrors" :key="b.id">#{{b.id}} {{b.source_name}} · {{b.rejected_rows}} 行异常</p></details><details><summary>缺课节数据（最多展示500条）</summary><p v-for="(s,i) in panel.missingLessons" :key="i">{{s.student_name}} · {{s.student_id}} · {{s.lesson_name}}</p></details>
<h3>预期班级与课节</h3><form v-if="hasPermission(editing?'rankings.expected.edit':'rankings.expected.create')" class="form-grid" @submit.prevent="saveLesson"><label>营期ID<input v-model="lesson.campId" required maxlength="100"></label><label>班级ID<input v-model="lesson.classId" required maxlength="100"></label><label>课节ID<input v-model="lesson.lessonId" required maxlength="100"></label><label>课节名称<input v-model="lesson.lessonName" required maxlength="200"></label><label>预计完成时间<input v-model="lesson.plannedAt" type="datetime-local" required></label><button class="button button-primary" :disabled="busy">{{editing?'保存修改':'新增预期课节'}}</button><button v-if="editing" type="button" class="button button-quiet" @click="editing=null">取消编辑</button></form><div class="scroll"><table><thead><tr><th>班级 / 课节</th><th>预计时间</th><th>操作</th></tr></thead><tbody><tr v-for="e in expected" :key="e.id"><td>{{e.camp_id}} / {{e.class_id}} · {{e.lesson_name}}</td><td>{{new Date(e.planned_at).toLocaleString()}}</td><td><button v-if="hasPermission('rankings.expected.edit')" class="button button-quiet" @click="editLesson(e)">修改</button><button v-if="hasPermission('rankings.expected.delete')" class="button button-danger" @click="removeLesson(e)">删除</button></td></tr></tbody></table></div></section>
<section v-if="auth.user?.admin"><h2>学生与教师交接</h2><p>仅最高管理员可操作。先预览再确认，原课程、订单归属保留，剩余可兑换积分随学生转移。</p><form class="form-grid" @submit.prevent="transferPreview"><label>原老师<select v-model="from" aria-label="原老师" required><option value="">请选择</option><option v-for="t in teachers" :value="t.username">{{t.username}}</option></select></label><label>接收老师<select v-model="to" aria-label="接收老师" required><option value="">请选择</option><option v-for="t in teachers.filter(t=>t.enabled)" :value="t.username">{{t.username}}</option></select></label><label>学生ID（逗号分隔）<input v-model="studentIds" :required="!offboard"></label><label><input v-model="offboard" type="checkbox">教师离职：交接全部在读学员并停用老师</label><label>原因 / 核实依据<input v-model="reason" required maxlength="255"></label><button class="button button-primary" :disabled="busy">预览交接</button></form><section v-if="preview" class="notice"><h3>{{preview.from}} → {{preview.to}}</h3><p v-for="s in preview.rows" :key="s.studentId">{{s.studentId}} · 转移 {{s.balance}} 积分</p><button class="button button-primary" :disabled="busy" @click="confirmTransfer">确认交接 {{preview.rows.length}} 位学员</button><button class="button button-quiet" @click="preview=null">取消</button></section><details><summary>当前归属与冲突</summary><div class="scroll"><table><thead><tr><th>学员</th><th>老师</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in owners" :key="o.student_id"><td>{{o.student_name}} · {{o.student_id}}</td><td>{{o.owner_username||'待核实'}}</td><td>{{o.state==='ACTIVE'?'有效':'归属冲突'}}</td><td><button v-if="o.state==='CONFLICT'" class="button button-quiet" :disabled="busy" @click="resolve(o)">指定为上方接收老师</button></td></tr></tbody></table></div></details></section></section></template>
<style scoped>.continuity{padding:20px;background:#fff;border:1px solid #d8e0e3;border-radius:10px;min-width:0;display:grid;gap:30px}.continuity section{min-width:0}.continuity h2{font-size:18px}.continuity p{color:#637984}.stats,.form-grid{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}.stats span{padding:10px;background:#eef7f5;border-radius:6px}.form-grid{align-items:end}.form-grid label{display:grid;gap:6px;flex:1 1 180px;font-size:13px}input,select{padding:10px;max-width:100%;min-width:0;border:1px solid #d8e0e3;border-radius:6px}input[type=checkbox]{width:18px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e3e9eb;text-align:left;min-width:100px}details{margin:12px 0}</style>
